referenceSolutions.javascript:
export function solve(calls, mapper) {
  let done = false,
    result = 0,
    evaluations = 0;
  const values = calls.map((x) => {
    if (!done) {
      result = x * mapper.factor + mapper.offset;
      done = true;
      evaluations++;
    }
    return result;
  });
  return { values, evaluations };
}

